# vim:ts=4 sw=4 expandtab softtabstop=4
from __future__ import annotations

import argparse
import base64
import binascii
import codecs
import io
import locale
import os
import sys
from typing import BinaryIO, Iterator, NoReturn, Optional, Sequence, Tuple

from unidecode import unidecode


def fatal(msg: str) -> NoReturn:
    sys.stderr.write(msg + "\n")
    raise SystemExit(1)


def _build_parser(default_encoding: str) -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Transliterate Unicode text into ASCII. FILE is path to file to "
            "transliterate. Standard input is used if FILE is omitted and -c "
            "is not specified."
        )
    )
    parser.add_argument(
        '-e',
        '--encoding',
        metavar='ENCODING',
        default=default_encoding,
        help='Specify an encoding (default is %s)' % (default_encoding,),
    )
    parser.add_argument(
        '-c',
        metavar='TEXT',
        dest='text',
        help='Transliterate TEXT instead of FILE',
    )
    parser.add_argument(
        '-b',
        '--base64',
        dest='base64_input',
        action='store_true',
        help=(
            'Decode input as base64 before applying the selected encoding. '
            'Useful for safely passing non-ASCII text on platforms with '
            'limited shell encoding support.'
        ),
    )
    parser.add_argument('path', nargs='?', metavar='FILE')
    return parser


def _open_stream(args: argparse.Namespace) -> Tuple[BinaryIO, bool]:
    if args.path is not None:
        if args.text is not None:
            fatal("Can't use both FILE and -c option")
        try:
            return open(args.path, 'rb'), False
        except OSError as exc:
            fatal('Unable to open input file %r: %s' % (args.path, exc))

    if args.text is not None:
        return io.BytesIO(os.fsencode(args.text)), True

    return sys.stdin.buffer, False


def _decode_base64(data: bytes) -> bytes:
    normalized = b''.join(data.split())

    try:
        return base64.b64decode(normalized, validate=True)
    except (binascii.Error, ValueError) as exc:
        fatal('Unable to decode base64 input: %s' % (exc,))


def _iter_chunks(stream: BinaryIO, from_command_line: bool, use_base64: bool) -> Iterator[Tuple[int, bytes]]:
    if use_base64:
        decoded = _decode_base64(stream.read())
        if from_command_line:
            decoded += b'\n'
        if decoded:
            yield 0, decoded
        return

    if from_command_line:
        yield 0, stream.read() + b'\n'
        return

    for line_nr, line in enumerate(stream):
        yield line_nr, line


def _decode_chunk(data: bytes, encoding: str, line_nr: int) -> str:
    try:
        return data.decode(encoding)
    except UnicodeDecodeError as exc:
        fatal('Unable to decode input line %s: %s, start: %d, end: %d' % (
            line_nr, exc.reason, exc.start, exc.end))
    except LookupError:
        fatal('Unknown encoding: %s' % (encoding,))


def _validate_encoding(encoding: str) -> str:
    try:
        codecs.lookup(encoding)
    except LookupError:
        fatal('Unknown encoding: %s' % (encoding,))

    return encoding


def main(argv: Optional[Sequence[str]] = None) -> None:
    default_encoding = locale.getpreferredencoding(False)
    args = _build_parser(default_encoding).parse_args(argv)
    encoding = _validate_encoding(args.encoding)
    stream, from_command_line = _open_stream(args)

    try:
        for line_nr, data in _iter_chunks(stream, from_command_line, args.base64_input):
            sys.stdout.write(unidecode(_decode_chunk(data, encoding, line_nr)))
    finally:
        if stream is not sys.stdin.buffer:
            stream.close()

